import{_ as e,o as i,a as r,d as t}from"./chunks/framework.MWxrmMMs.js";const p=JSON.parse('{"title":"Анализатор логов","description":"Анализатор логов Minecraft в Stuzhik: главная причина краша по устройству отчёта, шаги с кнопками, которые сверяются со сборкой, история крашей и архив логов для автора мода.","frontmatter":{"description":"Анализатор логов Minecraft в Stuzhik: главная причина краша по устройству отчёта, шаги с кнопками, которые сверяются со сборкой, история крашей и архив логов для автора мода.","head":[["meta",{"name":"keywords","content":"minecraft crash analyzer, stuzhik, стужик, анализ логов minecraft, почему вылетает minecraft, minecraft crash fix, mixin crash, краш репорт minecraft"}]]},"headers":[],"relativePath":"guide/log-analyzer.md","filePath":"guide/log-analyzer.md"}'),o={name:"guide/log-analyzer.md"};function l(n,a,s,c,h,d){return i(),r("div",null,[...a[0]||(a[0]=[t('<h1 id="анализатор-логов" tabindex="-1">Анализатор логов <a class="header-anchor" href="#анализатор-логов" aria-label="Permalink to &quot;Анализатор логов&quot;">​</a></h1><p>Анализатор читает crash-report и логи игры и говорит, почему она упала и что с этим сделать. Он разбирает сам отчёт: стек вызовов, раздел <code>Mixins in Stacktrace</code> и моды, которые в нём названы. Поэтому виновника он называет по тому, где упал код, а не по тому, какой мод чаще всего упоминается в логе. На 93 настоящих крашах из трекеров модов он назвал верную причину в 90 и ни разу не обвинил не тот мод. Тексты отчёта на языке интерфейса лаунчера.</p><h2 id="когда-он-запускается" tabindex="-1">Когда он запускается <a class="header-anchor" href="#когда-он-запускается" aria-label="Permalink to &quot;Когда он запускается&quot;">​</a></h2><ul><li><strong>После краша сам.</strong> Лаунчер разбирает лог упавшей игры, кладёт разбор в «Историю крашей» и открывает анализатор. Даже если окно лаунчера было закрыто, краш попадёт в историю</li><li><strong>Вручную</strong>: вкладка «Анализ логов» на странице сборки. «Проверить снова» разбирает логи ещё раз</li><li><strong>Без окна</strong>: <code>stuzhik-cli analyze</code> в <a href="/guide/cli.html">консольной версии</a> печатает тот же разбор</li></ul><h2 id="live-monitoring" tabindex="-1">Во время игры <a class="header-anchor" href="#live-monitoring" aria-label="Permalink to &quot;Во время игры {#live-monitoring}&quot;">​</a></h2><p>Пока игра идёт, «Live-мониторинг» в заголовке окна следит за её логом и показывает ошибки и предупреждения ещё до краша. Ошибка загрузки (скрипт KubeJS, конфликт mixin) сразу открывает анализатор.</p><h2 id="solutions" tabindex="-1">Главная причина <a class="header-anchor" href="#solutions" aria-label="Permalink to &quot;Главная причина {#solutions}&quot;">​</a></h2><p>Сверху карточка с главной причиной: что случилось, в каком моде, и строка этого мода в сборке (какая версия стоит или что мода в сборке нет). Под ней «Что сделать»: шаги по порядку, у каждого своя кнопка:</p><ol><li><strong>Обновить</strong>: анализатор сам проверяет, есть ли версия новее для этой сборки, и показывает, до какой обновит. Если новее нет или версия закреплена, так и пишет, вместо кнопки, которая ничего не сделает</li><li><strong>Отключить</strong>: мод выключается в сборке, «Включить обратно» возвращает его. Если мод уже отключён, шаг это говорит</li><li><strong>Сообщить автору</strong>: «Архив логов» собирает логи этого запуска в <code>.zip</code>, «Страница мода» и «Трекер ошибок» ведут туда, куда его отправить</li></ol><p>Каждая кнопка отвечает на нажатие сразу («Обновление…», «Отключение…»), а результат пишет в самом шаге: «обновлён до …, запустите игру». Ошибка видна под шагом.</p><p>«Как это определено» раскрывает строки отчёта, по которым это решено. «Подробнее и поиск решений» открывает полное описание проблемы.</p><h2 id="еще-нашлось" tabindex="-1">Ещё нашлось <a class="header-anchor" href="#еще-нашлось" aria-label="Permalink to &quot;Ещё нашлось&quot;">​</a></h2><p>Под главной причиной видно остальное, что анализатор узнал в логе: нехватка памяти, повреждённый конфиг, не та Java и другое. У проблем, которые лаунчер умеет исправить сам, есть кнопка действия («Увеличить выделенную память», «Переустановить мод», «Установить/обновить Fabric API» и подобные). «Исправить все проблемы» показывает список исправлений, выбранные применяются кнопкой «Применить выбранные».</p><p>«Не проблема» скрывает находку в этой сборке, и при следующих разборах она не предлагается. Вернуть её: «Управление скрытыми».</p><h2 id="меню-«еще-деиствия»-⋯" tabindex="-1">Меню «Ещё действия» (⋯) <a class="header-anchor" href="#меню-«еще-деиствия»-⋯" aria-label="Permalink to &quot;Меню «Ещё действия» (⋯)&quot;">​</a></h2><ul><li>«Отдельный лог-файл»: разобрать один из логов сборки, а не последний запуск</li><li>«Открыть лог с диска…»: любой лог или crash-report, не обязательно из Stuzhik</li><li>«Сохранить отчёт» и «Открыть сохранённый отчёт…»: разбор в файл и обратно</li><li>«Архив логов для автора мода»: <code>latest.log</code>, конец <code>debug.log</code>, последние crash-report&#39;ы и разбор Stuzhik в одном <code>.zip</code></li><li>«Копировать как Markdown»: отчёт в буфер обмена, чтобы вставить в чат или issue на GitHub</li><li>«Какие исправления разрешены»: список исправлений, которые лаунчер может применить сам</li></ul><h2 id="история-крашеи" tabindex="-1">История крашей <a class="header-anchor" href="#история-крашеи" aria-label="Permalink to &quot;История крашей&quot;">​</a></h2><p>Вторая вкладка рядом с «Анализом логов». «Статистика»: сколько было крашей, за неделю, какие моды чаще виноваты и сколько исправлено. «История»: каждый краш с его разбором, «Отметить решённым» помечает исправленный. «Тренды»: стало ли крашей больше или меньше. «Очистить историю» удаляет записи этой сборки.</p><h2 id="если-ничего-не-нашлось" tabindex="-1">Если ничего не нашлось <a class="header-anchor" href="#если-ничего-не-нашлось" aria-label="Permalink to &quot;Если ничего не нашлось&quot;">​</a></h2><p>«Проблем не обнаружено» значит, что в логах нет ничего из того, что анализатор знает и что мешает игре. Тогда пригодится «Архив логов для автора мода»: отправьте его в <a href="https://t.me/stuzhik_launcher" target="_blank" rel="noreferrer">Telegram</a> или автору мода.</p>',20)])])}const m=e(o,[["render",l]]);export{p as __pageData,m as default};
